const meta = $('Join').first().json;
const md = String($input.first().json.markdown || '').normalize('NFC');
const MAX = 1500;

const strip = s => s.normalize('NFD').replace(/\p{M}/gu, '').replace(/đ/g, 'd').replace(/Đ/g, 'D').toLowerCase();
const fmt = d => { const [y, m, dd] = d.split('-'); return `${dd}/${m}/${y}`; };

// 1) tách theo Chương / Điều / heading
let chuong = '', dieu = '', buf = [];
const sections = [];
const flush = () => { const t = buf.join('\n').trim(); if (t) sections.push({ chuong, dieu, text: t }); buf = []; };
for (const line of md.split(/\r?\n/)) {
  const l = line.replace(/^#+\s*/, '').replace(/\*\*/g, '').trim();
  if (/^chương\s+[ivxlc0-9]+/i.test(l)) { flush(); chuong = l; dieu = ''; continue; }
  if (/^điều\s+\d+/i.test(l) || /^#{1,3}\s+/.test(line)) { flush(); dieu = l; }
  buf.push(line);
}
flush();

// 2) tách khối bảng ra khỏi văn bản
const tableRe = /(?:^[ \t]*\|.*\|[ \t]*(?:\n|$))+/gm;
function pieces(text) {
  const res = []; let last = 0, m; tableRe.lastIndex = 0;
  while ((m = tableRe.exec(text))) {
    if (m.index > last) res.push({ type: 'text', text: text.slice(last, m.index) });
    res.push({ type: 'table', text: m[0] }); last = m.index + m[0].length;
  }
  if (last < text.length) res.push({ type: 'text', text: text.slice(last) });
  return res.filter(p => p.text.trim());
}

// 3) Điều dài thì tách theo Khoản; còn quá dài thì cắt cứng có overlap
function hardSplit(t) { const out = [], step = Math.floor(MAX * 0.87); for (let i = 0; i < t.length; i += step) out.push(t.slice(i, i + MAX)); return out; }
function splitLong(text) {
  if (text.length <= MAX) return [text];
  const out = []; let cur = '';
  for (const p of text.split(/\n(?=\s*\d+[\.\)]\s)/)) {
    if (cur && (cur + '\n' + p).length > MAX) { out.push(cur); cur = p; } else cur = cur ? cur + '\n' + p : p;
  }
  if (cur) out.push(cur);
  return out.flatMap(o => o.length <= MAX * 1.3 ? [o] : hardSplit(o));
}

const rows = [];
for (const s of sections) {
  const path = [s.chuong, s.dieu].filter(Boolean).join(' > ') || meta.title;
  for (const p of pieces(s.text)) {
    const subs = p.type === 'table' ? [p.text] : splitLong(p.text);
    subs.forEach((txt, idx) => {
      const content = (p.type === 'table' ? `Bảng thuộc mục ${path}:\n` : '') + txt.trim();
      if (content.length < 20) return;
      const sp = path + (subs.length > 1 ? ` (phần ${idx + 1})` : '');
      const header = `[${meta.title} – ${meta.doc_number || 's/n'} – ${sp} – hiệu lực ${fmt(meta.effective_date)} – v${meta.version}]`;
      rows.push({
        chunk_id: crypto.randomUUID(), doc_version_id: meta.doc_version_id,
        chunk_type: p.type === 'table' ? 'table' : 'text',
        section_path: sp, contextual_header: header, content,
        content_unaccent: strip(sp + ' ' + content),
        embed_text: header + '\n' + content
      });
    });
  }
}
if (!rows.length) throw new Error('Không tách được chunk nào, hãy kiểm tra bản Markdown');
return [{ json: { rows } }];"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[448,0],"id":"1ed4a94d-05aa-4758-8955-c6d90d33d1cd","name":"Chunk"},{"parameters":{"operation":"executeQuery","query":"INSERT INTO documents (doc_version_id, document_id, version, title, doc_number, issue_date,
